const a={ocnal:{baipishu:"Buku Putih",home1:"Buka dunia mata wang digital",home2:"Deposit sekarang",home3:"Nama",home4:"Harga",home5:"Perubahan 24 jam",home6:"Dagangan",home7:"Mulakan sekarang",home8:"Cipta akaun",home9:"Daftar akaun untuk menikmati lebih banyak keistimewaan dan perkhidmatan",home10:"Daftar",home11:"Deposit dana",home12:"Tambah nilai akaun anda dan mula melabur dalam mata wang kripto",home13:"Deposit kripto",home14:"Mula berdagang",home15:"Jual, beli atau salin dagangan dan temui lebih banyak peluang",home16:"Terokai pasaran",home17:"Pasaran mata wang kripto sedang berkembang pesat, merangkumi mata wang digital, teknologi blockchain dan banyak lagi. Peluangnya cerah tetapi pelaburan memerlukan berhati-hati.",home18:"Spot",home19:"Dagangan masa nyata dengan perubahan harga yang pantas.",home20:"Kontrak kekal",home21:"Dagangan kontrak menawarkan leverage untuk potensi pulangan tinggi.",home22:"Opsyen",home23:"Dagangan opsyen menyediakan strategi lindung nilai yang fleksibel untuk mengawal risiko dan menjana pulangan.",home24:"Pelaburan AI",home25:"Rancang dengan yakin. Melabur dengan bijak. Kurangkan kebimbangan.",home26:"Pulangan tahunan tertinggi dalam sejarah",home27:"Semasa",home28:"Tetap",home29:"Beli sekarang",home30:"Semua orang boleh menggunakan mata wang digital",home31:"Daripada pengalaman pertama berdagang kripto hingga pembelian pertama produk kewangan, platform ini membantu anda menjana keuntungan dengan mudah.",home32:"Ketahui tentang kripto",home33:"Pelajari segala-galanya tentang kripto untuk mula melabur",home34:"Soalan lazim",home35:"Sedia untuk memulakan perjalanan kripto anda?",home36:"Apakah itu pertukaran mata wang kripto?",home37:"Pertukaran kripto ialah pasaran digital yang membolehkan pengguna membeli dan menjual mata wang kripto seperti Bitcoin, Ethereum dan Tether. Binance ialah pertukaran terbesar mengikut volum dagangan.",home38:"Apakah produk yang ditawarkan oleh platform?",home39:"Sebagai platform perdagangan kripto terkemuka di dunia, ia kini berkhidmat kepada lebih 150 juta pengguna berdaftar di lebih 180 negara. Dengan yuran rendah, ia menawarkan lebih daripada 350 mata wang kripto untuk didagangkan.<br><br>Di platform ini pengguna boleh:<br><br>1. Berdagang ratusan mata wang digital dan pasangan dagangan.<br><br>2. Membeli dan menjual kripto melalui dagangan spot.<br><br>3. Menjana faedah melalui pengurusan aset kripto.",home40:"Cara berdagang kripto di platform",home41:"Di platform ini anda boleh berdagang ratusan kripto di pasaran spot, niaga hadapan dan opsyen. Daftar akaun, sahkan identiti anda dan deposit atau beli kripto untuk mula berdagang.",home42:"Adakah platform ini selamat?",home43:"Platform ini komited untuk menyediakan persekitaran dagangan yang selamat dan boleh dipercayai. Kami mempunyai teknologi keselamatan canggih dan pasukan berdedikasi untuk melindungi aset anda. Semua aset pengguna disokong 1:1 sepenuhnya.",home44:"Bagaimana jika terlupa kata laluan?",home45:"Klik 'Lupa Kata Laluan' di halaman log masuk untuk menetapkannya semula.",home46:"Mengapa perlu pengesahan identiti?",home47:"Untuk keselamatan dana anda dan mencegah aktiviti pengubahan wang haram, kami perlu memastikan akaun penerimaan dikaitkan dengan identiti semasa anda.",home48:"Pasaran",home49:"Pasaran perdagangan mata wang kripto global menyokong transaksi pelbagai mata wang, menawarkan keselamatan dan kecekapan.",home50:"Akaun saya",home51:"Deposit",home52:"Pengeluaran",home53:"Tukar",home54:"Hangat",home55:"Melabur dalam token baharu yang diterbitkan dan nikmati pulangan berpotensi tinggi",home56:"Berita",home57:"Mengapa pilih kami?",home58:"Dipercayai oleh berjuta-juta pengguna",home59:"Bilangan pengguna",home60:"Unit rakan kongsi",home61:"Yuran transaksi minimum",home62:"Rakan kongsi",home63:"Volum 24 jam",home64:"Membuka era baharu kekayaan digital",home65:"Berdagang dengan selamat, melabur dengan mudah",home66:"Mula sekarang",home67:"Dagangan pintar, masa depan terhubung",home68:"Dagangan pantas, jangan lepaskan peluang",home69:"Aset digital, mudah dicapai",jianguanzhengshu:"Sijil Pengawalseliaan",falvzhengmingshu:"Sijil Perundangan",withdrawNote:"Notis Pengeluaran:<br><br>Masa pemprosesan pengeluaran adalah 24 jam<br><br>Selepas menghantar permintaan pengeluaran dana, dana akan dibekukan kerana pengeluaran sedang diproses dan disimpan sementara oleh sistem. Ini tidak bermakna aset anda hilang atau terdapat sebarang anomali.<br><br>Permintaan pengeluaran token akan dikreditkan dalam masa 12 jam selepas penyerahan. Jika pengeluaran token tidak dikreditkan selepas masa ketibaan yang dijangkakan, sila hubungi perkhidmatan pelanggan dalam talian.<br><br>Pengeluaran amaun besar mesti dilakukan oleh ahli VIP kami. Sila hubungi perkhidmatan pelanggan dalam talian untuk maklumat lanjut."},yingshe:{miaoheyue:"Dagangan Opsyen",miaoheyuejiaoyi:"Dagangan Opsyen",heyuezhanghu:"Akaun Dagangan"},deltax:{company_bylaws:"Peraturan syarikat",good_standing_certificate:"Sijil berdiri baik",about_title:"Tentang Kami",about_text_1:"Kami adalah salah satu platform perdagangan yang berkembang paling pesat di Eropah, dengan pejabat di UK, Eropah, dan Australia. Kami sentiasa meletakkan pelanggan di pusat setiap keputusan yang kami buat, mempromosikan perdagangan mereka melalui teknologi intuitif, pendidikan mendalam, dan sokongan berdedikasi.",about_text_2:"Misi kami adalah untuk menyediakan alat dan sumber yang diperlukan oleh peniaga untuk berdagang dengan yakin dan membuat keputusan yang lebih baik. Misi ini telah memenangi pelbagai anugerah daripada pihak berkuasa industri terkemuka.",stats_title:"Gambaran Pertumbuhan",stat_global_label:"Operasi Global",stat_global_desc:"Seiring dengan pertambahan bilangan pejabat global kami, kami bangga dapat berkhidmat kepada pelanggan di 183 negara dan wilayah",stat_global_link:"Ketahui tentang perdagangan",stat_traders_label:"Pedagang",stat_traders_desc:"Sejak dilancarkan, komuniti pedagang global kami telah berdagang dengan volum lebih daripada 53 bilion dolar AS",stat_traders_link:"Lihat berita terkini",stat_support_label:"Kakitangan Sokongan",stat_support_desc:"Pasukan perkhidmatan pelanggan mesra kami tersedia 24 jam dalam 12 bahasa untuk membantu anda dengan sebarang pertanyaan berkaitan akaun",stat_support_link:"Sokongan",promise_title:"Komitmen Kami kepada Pelanggan",promise_desc:"Perdagangan adalah kemahiran yang hanya sedikit orang yang benar-benar menguasainya. Tetapi kami percaya bahawa dengan menggabungkan teknologi inovatif, pendidikan imersif, dan pandangan unik mengenai tingkah laku perdagangan dengan betul, sesiapa sahaja boleh mengembangkan kepakaran perdagangan di pasaran. Sama ada anda pedagang berpengalaman atau pemula, kami menyediakan alat yang anda perlukan untuk meningkatkan pengetahuan dan kemahiran anda.",promise_customer_name:"Pelanggan Didahulukan",promise_customer_text:"Dibina oleh pedagang, kami menggunakan penyelidikan khusus, sains data, dan pandangan unik untuk membangunkan produk yang memberi inspirasi kepada pelanggan kami untuk meningkat",promise_innovation_name:"Tidak Pernah Berhenti",promise_innovation_text:"Kami komited untuk terus mengoptimumkan platform kami untuk menyampaikan pengalaman pengguna yang lancar dan membolehkan perdagangan yakin serta keputusan yang lebih baik melalui alat inovatif yang berpusatkan teknologi",promise_transparency_name:"Sentiasa Telus",promise_transparency_text:"Kami berusaha untuk menghapuskan halangan perdagangan dengan menawarkan beberapa penentuan harga paling kompetitif dalam industri, bersama dengan sumber pendidikan yang mudah digunakan dan kaya",promise_expertise_name:"Kepakaran Utama",promise_expertise_text:"Pasukan antarabangsa kami membawa puluhan tahun teknologi dan kepakaran perdagangan, meletakkan asas untuk platform yang mesra pengguna, berpusatkan teknologi, dan intuitif",expertise_title:"Kepakaran Kami",expertise_text_1:"Sebagai broker yang memenangi anugerah, kami diiktiraf oleh pelanggan kami kerana pengalaman pengguna intuitif yang didorong oleh teknologi, sokongan pelanggan berkualiti tinggi, dan nilai yang sangat baik. Teknologi adalah teras segala yang kami lakukan, menawarkan ciri pintar seperti data pasaran masa nyata, alat carta lanjutan, dan aplikasi mudah alih responsif yang menyokong perdagangan mudah alih. Matlamat kami adalah untuk menyediakan akses tanpa sekatan kepada peniaga runcit untuk instrumen kewangan global.",expertise_text_2:"Kami sentiasa mencari cara baharu untuk membantu pelanggan berdagang dengan yakin dan membuat keputusan yang lebih bijak, menyampaikan teknologi terkini, sumber pendidikan mendalam, dan penentuan harga kompetitif dalam persekitaran perdagangan yang sentiasa berubah.",expertise_stat_traders:"Pedagang",expertise_stat_service:"Perkhidmatan Pelanggan",expertise_stat_unit_second:"s",expertise_stat_speed_label:"Kelajuan pelaksanaan purata",expertise_stat_indicators:"Petunjuk teknikal",expertise_footnote:"Berdasarkan data pelayan dalaman kami pada 2022",awards_title:"Pengiktirafan Industri",awards_desc_1:"Produk intuitif kami, perkhidmatan pelanggan yang berdedikasi, dan inovasi berterusan telah berkali-kali diiktiraf oleh beberapa pihak berkuasa terkemuka dalam industri.",awards_desc_2:"Pada tahun 2023, Deloitte Technology Fast 50 menempatkan kami sebagai salah satu daripada 50 syarikat teknologi yang berkembang paling pesat di Timur Tengah dan Cyprus. Berikut adalah beberapa anugerah terkini kami:",products_title:"Produk dan Perkhidmatan Kami",product_cfd_name:"Perdagangan CFD",product_cfd_desc:"Pergi long atau short pada forex, indeks, saham, komoditi, dan banyak lagi, tanpa tarikh tamat tetap dan tanpa duti setem pada saham UK",product_platform_name:"Platform Mesra Pengguna",product_platform_desc:"Kami mengutamakan kemudahan penggunaan untuk pelanggan kami, membolehkan perdagangan melalui desktop, mudah alih, dan API",product_demo_name:"Akaun Demo Perdagangan",product_demo_desc:"Peniaga boleh mencuba platform kami tanpa risiko dengan dana maya sambil menambah baik strategi perdagangan mereka",product_education_name:"Pendidikan",product_education_desc:"Menyediakan pandangan mendalam mengenai pemandu pasaran fundamental dan teknikal terkini untuk membantu pedagang membuat keputusan yang berinformasi",product_more:"Lagi",products_footnote:"Rawatan cukai bergantung pada keadaan individu dan mungkin berubah atau berbeza di bidang kuasa di luar UK",global_title:"Pejabat Global",award_source_good_money:"Good Money Guide",award_source_online_money:"Online Money Awards",award_source_forexbrokers:"ForexBrokers.com",award_source_investment_trends:"Investment Trends",award_source_advfn:"ADVFN",award_source_ft:"Financial Times Investors’ Chronicle",award_good_money_guide:"Aplikasi Perdagangan Terbaik 2023",award_online_money:"Penyedia CFD Terbaik 2023",award_forexbrokers:"Broker Pertumbuhan Terpantas 2023",award_investment_satisfaction:"Kepuasan Pelanggan Keseluruhan 2022",award_investment_value:"Nilai Terbaik untuk Wang 2022",award_advfn:"Broker Pertumbuhan Terpantas 2023",award_ft_investors:"Sokongan Pelabur Baharu 2022"},licai:{zhiyawakuang:"Hasil Pintar",zhiyawakuangjiaoyi:"Perdagangan Hasil Pintar"}};export{a as default};
